import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"24、【復】 震下坤上","description":"周易口訣義 - 24、【復】 震下坤上","frontmatter":{"title":"24、【復】 震下坤上","description":"周易口訣義 - 24、【復】 震下坤上"},"headers":[],"relativePath":"classics/koujueyi/026.md","filePath":"classics/koujueyi/026.md"}'),r={name:"classics/koujueyi/026.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_24、【復】-震下坤上" tabindex="-1">24、【復】 震下坤上 <a class="header-anchor" href="#_24、【復】-震下坤上" aria-label="Permalink to “24、【復】 震下坤上”">​</a></h1><p>彖曰：「復，亨」。剛反動而以順行，是以「出入無疾，朋來無咎」。「反覆其道，七日來複」，天行也。「利有攸往」，剛長也。復，其見天地之心乎！</p><p>象曰：雷在地中，復，先王以至日閉關，商旅不行，後不省方。</p><p>初九，不遠復，無祇悔，元吉。</p><p>象曰：「不遠」之復，以修身也。</p><p>六二，休復，吉。</p><p>象曰：「休復」之吉，以下仁也。</p><p>六三，頻復，厲無咎。</p><p>象曰：「頻復」之厲，義無咎也。</p><p>六四，中行獨復。</p><p>象曰：「中行獨復」，以從道也。</p><p>六五，敦復，無悔。</p><p>象曰：「敦復無悔」，中以自考也。</p><p>上六，迷復，兇，有災眚。用行師，終有大敗，以其國君兇，至於十年不克徵。</p><p>象曰：「速復」之兇，反君道也。</p><p>解讀</p><p>復亨者，復是歸本之名，靜默為義，故老子云：「歸根曰靜，是謂覆命」也。陽氣反覆，所以亨通，故曰「亨」也。「出入無疾，朋來無咎」者，出則剛長，入則陽復，理會其時，故「無疾」；朋謂眾陽，以陽氣漸長，眾陽朋聚而來，故「無咎」。「反覆其道，七日來複」者，反之與復，理會其宜，故曰「反覆其道」；陽氣滅絕之後，不過七日，陽復生來，故云「七日來複」。「利有攸往」，以陽氣漸盛，陰柔乃消，故利有所往。象曰：雷在地中，復。以靜默為義。雷本動物，今在地中，靜默之象。「先王以至日閉關，商旅不行，後不省方」者，方，事也。先王於至之日，閉塞視聽，不親其事，商旅不行道路，在於君後，亦不省察四方之事也。</p><p>初九，不遠復，無祇悔，元吉。祇，大也。最處復初，初知福之機，不為迷遠，尋能求復，歸於善道，故無大悔，而終獲大吉也。</p><p>六二，休復，吉。處復之時，近初之陽，是親仁善鄰，既親賢德之行，而獲休美之吉。</p><p>六三，頻復，厲，無咎。頻，蹙之貌也。六三去復已遠，雖勝上六之迷暗，猶可頻蹙而復於危厲之中，而得無咎也。</p><p>六四，中行獨復。獨應於初，即是棄惡歸善。處四陰之中，獨得善道，故曰「中行獨復」。</p><p>「六五，敦復，無悔」者，敦，厚也。處尊位，以敦厚之德，而能考成其行，故無悔而已也。</p><p>「上六，迷復，兇，有災眚，用行師，終有大敗，以其國君兇，至於十年不克徵」者，上為最處復後，是迷暗而更求復也。以迷求復，去善既遠，必致兇災，故曰「迷復兇，有災眚」。用此迷暗之人興行師旅，終有大敗。若用於其國內，即反違君道，故曰「用行師，終有大敗」，以其國君兇也。縱使修身改悔，至於十年猶不能徵進矣，故曰「至於十年不克徵」。傷害曰災，妖祥曰眚。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
